  const cursorY = interpolate(cursorMoveProgress, [0, 1], [startY, targetY]);

  // Scales & Colors
  const buttonScale =
    1 + hoverScaleProgress * 0.02 - clickDownProgress * 0.04 + clickUpProgress * 0.04;
  const cursorScale = 1 - clickDownProgress * 0.15 + clickUpProgress * 0.15;

